const views=[...document.querySelectorAll('.view')];const nav=[...document.querySelectorAll('[data-view]')];function show(id){views.forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('header nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'})}nav.forEach(b=>b.addEventListener('click',()=>show(b.dataset.view)));const drawer=document.querySelector('#drawer'),shade=document.querySelector('#shade'),roomTitle=document.querySelector('#drawer-room');function openRoom(name='Room 3'){roomTitle.textContent=name;drawer.classList.add('open');shade.classList.add('on')}function closeRoom(){drawer.classList.remove('open');shade.classList.remove('on')}document.querySelectorAll('.room.open').forEach(r=>r.addEventListener('click',()=>openRoom(r.dataset.room)));document.querySelector('#find-room').addEventListener('click',()=>openRoom('Room 3'));document.querySelector('#close').addEventListener('click',closeRoom);shade.addEventListener('click',closeRoom);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeRoom()});